package io.forgeloop.control.application;
import io.forgeloop.control.domain.*;
import java.nio.charset.StandardCharsets; import java.security.*; import java.time.*; import java.util.HexFormat; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service public class TaskLeaseService { private final DeliveryTaskRepository tasks; private final RunnerRepository runners; private final TaskLeaseRepository leases; private final SecureRandom random=new SecureRandom(); public TaskLeaseService(DeliveryTaskRepository tasks,RunnerRepository runners,TaskLeaseRepository leases){this.tasks=tasks;this.runners=runners;this.leases=leases;} @Transactional public LeaseGrant claim(String taskId,String runnerId){DeliveryTask task=tasks.findById(taskId).orElseThrow(()->new IllegalArgumentException("Task not found"));Runner runner=runners.findById(runnerId).orElseThrow(()->new IllegalArgumentException("Runner not found"));if(!runner.isEnabled())throw new IllegalStateException("Runner is disabled");if(task.getState()!=TaskState.PENDING&&task.getState()!=TaskState.REPAIR_QUEUED)throw new IllegalStateException("Task is not claimable");TaskLease existing=leases.findByTaskId(taskId).orElse(null);if(existing!=null&&existing.active())throw new IllegalStateException("Task already has an active lease");byte[] bytes=new byte[32];random.nextBytes(bytes);String nonce=HexFormat.of().formatHex(bytes);TaskLease lease=leases.save(new TaskLease(task,runner,hash(nonce),Instant.now().plus(Duration.ofMinutes(10))));task.transition(TaskState.LEASED);return new LeaseGrant(lease,nonce);} private String hash(String raw){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(raw.getBytes(StandardCharsets.UTF_8)));}catch(Exception ex){throw new IllegalStateException(ex);}} }
